#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ks(n);
    vector<vector<pair<int,int>>> cells(n);
    int totalCells = 0;
    for(int i = 0; i < n; i++){
        cin >> ks[i];
        cells[i].resize(ks[i]);
        for(int j = 0; j < ks[i]; j++){
            cin >> cells[i][j].first >> cells[i][j].second;
        }
        totalCells += ks[i];
    }

    // Transform: flip f (0 or 1: reflect x), then rotate r times 90° CCW
    // CCW rotation: (x,y) -> (-y,x)
    auto transform = [](vector<pair<int,int>>& src, int f, int r) -> vector<pair<int,int>> {
        vector<pair<int,int>> res;
        for(auto [x, y] : src){
            int nx = x, ny = y;
            if(f) nx = -nx; // flip over y-axis
            for(int q = 0; q < r; q++){
                int tmp = nx;
                nx = -ny;
                ny = tmp;
            }
            res.push_back({nx, ny});
        }
        // Normalize to non-negative
        int minx = INT_MAX, miny = INT_MAX;
        for(auto [x,y] : res){ minx = min(minx,x); miny = min(miny,y); }
        for(auto& [x,y] : res){ x -= minx; y -= miny; }
        return res;
    };

    struct OriInfo {
        vector<pair<int,int>> cells;
        int w, h;
        int f, r;
    };

    vector<vector<OriInfo>> allOris(n);
    for(int i = 0; i < n; i++){
        set<vector<pair<int,int>>> seen;
        for(int f = 0; f < 2; f++){
            for(int r = 0; r < 4; r++){
                auto tc = transform(cells[i], f, r);
                sort(tc.begin(), tc.end());
                if(seen.insert(tc).second){
                    int w = 0, h = 0;
                    for(auto [x,y] : tc){ w = max(w, x+1); h = max(h, y+1); }
                    allOris[i].push_back({tc, w, h, f, r});
                }
            }
        }
    }

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){
        return ks[a] > ks[b];
    });

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now() - startTime).count();
    };

    int sqA = max(1, (int)ceil(sqrt((double)totalCells)));

    long long bestArea = (long long)1e18;
    int bestH = 0, bestW = 0;
    struct Placement { int x, y, r, f; };
    vector<Placement> bestPlacements(n);
    bool haveSolution = false;

    for(int W = max(1, sqA/2); W <= totalCells + 10 && elapsed() < 9.0; W++){
        int maxH = totalCells + 10;
        vector<int> heightmap(W, 0);
        set<long long> occupied;

        vector<Placement> placements(n);
        int curMaxY = 0;
        bool failed = false;

        for(int idx = 0; idx < n && !failed; idx++){
            int pi = order[idx];
            int bestScore = INT_MAX;
            int bx=-1, by=-1, boi=-1;

            for(int oi = 0; oi < (int)allOris[pi].size(); oi++){
                auto& ori = allOris[pi][oi];
                if(ori.w > W) continue;
                for(int x = 0; x <= W - ori.w; x++){
                    int minY = 0;
                    for(auto [cx,cy] : ori.cells)
                        minY = max(minY, heightmap[x+cx] - cy);
                    int topY = 0;
                    for(auto [cx,cy] : ori.cells) topY = max(topY, minY+cy+1);
                    bool ok = true;
                    for(auto [cx,cy] : ori.cells){
                        long long key = (long long)(x+cx)*maxH + (minY+cy);
                        if(occupied.count(key)){ ok=false; break; }
                    }
                    if(ok){
                        int score = topY*10000 + x;
                        if(score < bestScore){ bestScore=score; bx=x; by=minY; boi=oi; }
                    }
                }
            }
            if(bx==-1){ failed=true; break; }
            auto& ori = allOris[pi][boi];
            for(auto [cx,cy] : ori.cells){
                occupied.insert((long long)(bx+cx)*maxH + (by+cy));
                heightmap[bx+cx] = max(heightmap[bx+cx], by+cy+1);
                curMaxY = max(curMaxY, by+cy+1);
            }
            placements[pi] = {bx, by, ori.r, ori.f};
        }
        if(failed) continue;
        long long area = (long long)W * curMaxY;
        if(area < bestArea){ bestArea=area; bestH=curMaxY; bestW=W; bestPlacements=placements; haveSolution=true; }
        if((long long)(W+1) * max(1, (totalCells+W)/(W+1)) > bestArea && haveSolution) break;
    }

    cout << bestW << " " << bestH << "\n";
    for(int i = 0; i < n; i++){
        cout << bestPlacements[i].x << " " << bestPlacements[i].y << " "
             << bestPlacements[i].r << " " << bestPlacements[i].f << "\n";
    }

    return 0;
}
